    auctionSentences: [
      { sentence:"Burning coal releases large amounts of carbon dioxide into the atmosphere.", isCorrect:true, explanation:"Correct: gerund subject 'Burning coal' takes the singular verb 'releases'." },
      { sentence:"Rising temperatures threaten the survival of many Arctic species.", isCorrect:true, explanation:"Correct: 'threaten + object' is correctly used." },
      { sentence:"Planting trees helps reduce the amount of carbon dioxide in the air.", isCorrect:true, explanation:"Correct: gerund subject 'Planting trees' with 'helps reduce' is correct." },
      { sentence:"Scientists warn that extreme weather events are becoming more frequent.", isCorrect:true, explanation:"Correct: comparative 'more frequent' is correctly used with 'becoming'." },
      { sentence:"Switching to solar power is one of the most effective ways to cut emissions.", isCorrect:true, explanation:"Correct: gerund subject and superlative 'most effective ways to' are correct." },
      { sentence:"Recycling plastic help reduce the amount of waste sent to landfill.", isCorrect:false, explanation:"The gerund subject 'Recycling plastic' is singular — use 'helps', not 'help'." },
      { sentence:"Melting glaciers is making sea levels rise more faster each year.", isCorrect:false, explanation:"'Faster' is already comparative — do not add 'more': 'rise faster'." },
      { sentence:"Droughts are becoming more worse in many parts of the world.", isCorrect:false, explanation:"'Worse' is already the comparative form of 'bad' — do not add 'more': 'becoming worse'." },
      { sentence:"Governments need to taking urgent action to reduce emissions.", isCorrect:false, explanation:"After 'need to', use the base verb: 'need to take', not 'need to taking'." },
      { sentence:"Coral reefs is dying at an alarming rate due to rising ocean temperatures.", isCorrect:false, explanation:"'Coral reefs' is plural — use 'are', not 'is'." },
    ],
